-- Simorgh v2 PostgreSQL schema; PostgreSQL 14+; idempotent and non-destructive.
BEGIN;
CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,phone VARCHAR(20) NOT NULL UNIQUE,password_hash TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','disabled')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles(user_id BIGINT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,display_name VARCHAR(100) NOT NULL DEFAULT '',first_name VARCHAR(80) NOT NULL DEFAULT '',last_name VARCHAR(80) NOT NULL DEFAULT '',bio VARCHAR(500) NOT NULL DEFAULT '',avatar_url TEXT,profile_visibility VARCHAR(16) NOT NULL DEFAULT 'public' CHECK(profile_visibility IN ('public','private')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,title VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS permissions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,code VARCHAR(80) NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS user_roles(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,assigned_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions(role_id BIGINT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS user_permissions(user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,permission_id BIGINT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,granted BOOLEAN NOT NULL DEFAULT TRUE,granted_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(user_id,permission_id));
CREATE TABLE IF NOT EXISTS points_ledger(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,amount INTEGER NOT NULL CHECK(amount<>0),reason VARCHAR(180) NOT NULL,reference_type VARCHAR(50),reference_id BIGINT,idempotency_key VARCHAR(200) UNIQUE,created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_points_user_created ON points_ledger(user_id,created_at DESC);

CREATE TABLE IF NOT EXISTS store_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,image_url TEXT,sort_order INTEGER NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS store_products(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id BIGINT REFERENCES store_categories(id) ON DELETE SET NULL,name VARCHAR(180) NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT,price BIGINT NOT NULL CHECK(price>=0),is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_store_products_category ON store_products(category_id,is_active);
CREATE TABLE IF NOT EXISTS cafe_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,image_url TEXT,sort_order INTEGER NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cafe_items(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id BIGINT REFERENCES cafe_categories(id) ON DELETE SET NULL,name VARCHAR(180) NOT NULL,description TEXT NOT NULL DEFAULT '',image_url TEXT,price BIGINT NOT NULL CHECK(price>=0),is_available BOOLEAN NOT NULL DEFAULT TRUE,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_cafe_items_category ON cafe_items(category_id,is_available);
-- Cafe is display-only; no cafe_orders table.
CREATE TABLE IF NOT EXISTS store_purchase_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,product_id BIGINT NOT NULL REFERENCES store_products(id) ON DELETE RESTRICT,quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0),unit_price_snapshot BIGINT NOT NULL CHECK(unit_price_snapshot>=0),status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','completed','cancelled')),note TEXT NOT NULL DEFAULT '',reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_store_requests_user ON store_purchase_requests(user_id,created_at DESC);

CREATE TABLE IF NOT EXISTS book_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,image_url TEXT,sort_order INTEGER NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS books(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_id BIGINT REFERENCES book_categories(id) ON DELETE SET NULL,title VARCHAR(220) NOT NULL,author VARCHAR(180) NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',image_url TEXT,book_type VARCHAR(12) NOT NULL CHECK(book_type IN ('loan','sale','both')),sale_price BIGINT CHECK(sale_price IS NULL OR sale_price>=0),loan_fee BIGINT NOT NULL DEFAULT 20000 CHECK(loan_fee>=20000),availability VARCHAR(20) NOT NULL DEFAULT 'available' CHECK(availability IN ('available','unavailable','archived')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(book_type<>'sale' OR sale_price IS NOT NULL));
CREATE TABLE IF NOT EXISTS book_purchase_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE RESTRICT,quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0),unit_price_snapshot BIGINT NOT NULL CHECK(unit_price_snapshot>=0),status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','completed','cancelled')),note TEXT NOT NULL DEFAULT '',reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_book_purchase_user ON book_purchase_requests(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS book_suggestions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,request_type VARCHAR(30) NOT NULL CHECK(request_type IN ('bring_from_store','donate_for_loan')),title VARCHAR(220) NOT NULL,author VARCHAR(180) NOT NULL DEFAULT '',description TEXT NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','completed')),reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS loan_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE RESTRICT,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled','fulfilled')),requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,note TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS idx_loan_requests_user ON loan_requests(user_id,requested_at DESC);
CREATE TABLE IF NOT EXISTS loans(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_request_id BIGINT NOT NULL UNIQUE REFERENCES loan_requests(id) ON DELETE RESTRICT,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,book_id BIGINT NOT NULL REFERENCES books(id) ON DELETE RESTRICT,loan_fee BIGINT NOT NULL CHECK(loan_fee>=20000),picked_up_at TIMESTAMPTZ NOT NULL,due_at TIMESTAMPTZ NOT NULL,returned_at TIMESTAMPTZ,fine_settled_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN ('active','returned','overdue','closed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(due_at>picked_up_at),CHECK(returned_at IS NULL OR returned_at>=picked_up_at));
CREATE UNIQUE INDEX IF NOT EXISTS uq_one_active_loan_per_user ON loans(user_id) WHERE status IN ('active','overdue');
CREATE INDEX IF NOT EXISTS idx_loans_due ON loans(due_at) WHERE status IN ('active','overdue');
CREATE TABLE IF NOT EXISTS loan_extensions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_id BIGINT NOT NULL REFERENCES loans(id) ON DELETE RESTRICT,requested_by BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','cancelled')),old_due_at TIMESTAMPTZ NOT NULL,new_due_at TIMESTAMPTZ,reviewed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ,CHECK(new_due_at IS NULL OR new_due_at>old_due_at));
CREATE UNIQUE INDEX IF NOT EXISTS uq_one_pending_extension_per_loan ON loan_extensions(loan_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS loan_fines(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_id BIGINT NOT NULL REFERENCES loans(id) ON DELETE RESTRICT,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,fine_date DATE NOT NULL,points_deducted INTEGER NOT NULL DEFAULT 10 CHECK(points_deducted>0),settled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(loan_id,fine_date));

CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(220) NOT NULL,description TEXT NOT NULL DEFAULT '',poster_url TEXT,starts_at TIMESTAMPTZ NOT NULL,ends_at TIMESTAMPTZ,event_type VARCHAR(20) NOT NULL CHECK(event_type IN ('weekly_notice','registration')),capacity INTEGER CHECK(capacity IS NULL OR capacity>=1),required_teammates INTEGER NOT NULL DEFAULT 0 CHECK(required_teammates>=0),status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','cancelled','completed')),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(ends_at IS NULL OR ends_at>starts_at),CHECK(event_type<>'weekly_notice' OR capacity IS NULL));
CREATE TABLE IF NOT EXISTS event_rule_versions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES events(id) ON DELETE RESTRICT,version INTEGER NOT NULL CHECK(version>0),rules_text TEXT NOT NULL,points_reward INTEGER NOT NULL DEFAULT 0 CHECK(points_reward>=0),created_by BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(event_id,version));
CREATE TABLE IF NOT EXISTS event_registrations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES events(id) ON DELETE RESTRICT,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,accepted_rule_version_id BIGINT NOT NULL REFERENCES event_rule_versions(id) ON DELETE RESTRICT,accepted_points INTEGER NOT NULL CHECK(accepted_points>=0),status VARCHAR(20) NOT NULL DEFAULT 'registered' CHECK(status IN ('registered','cancelled','attended','absent')),registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),cancelled_at TIMESTAMPTZ,cancellation_reason TEXT NOT NULL DEFAULT '',UNIQUE(event_id,user_id));
CREATE INDEX IF NOT EXISTS idx_event_registrations_event_status ON event_registrations(event_id,status);
CREATE TABLE IF NOT EXISTS event_attendees(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,registration_id BIGINT NOT NULL REFERENCES event_registrations(id) ON DELETE CASCADE,full_name VARCHAR(160) NOT NULL,phone VARCHAR(20) NOT NULL,is_account_owner BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_event_account_owner ON event_attendees(registration_id) WHERE is_account_owner=TRUE;
CREATE TABLE IF NOT EXISTS event_attendance(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,attendee_id BIGINT NOT NULL UNIQUE REFERENCES event_attendees(id) ON DELETE CASCADE,present BOOLEAN NOT NULL,marked_by BIGINT REFERENCES users(id) ON DELETE SET NULL,marked_at TIMESTAMPTZ NOT NULL DEFAULT now(),note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS event_penalties(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,registration_id BIGINT NOT NULL REFERENCES event_registrations(id) ON DELETE RESTRICT,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,penalty_type VARCHAR(30) NOT NULL CHECK(penalty_type IN ('late_cancellation','after_start_cancellation','absence')),points_deducted INTEGER NOT NULL CHECK(points_deducted>0),applied_ledger_id BIGINT UNIQUE REFERENCES points_ledger(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(registration_id,penalty_type));

CREATE TABLE IF NOT EXISTS forum_topics(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,created_by BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,title VARCHAR(220) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forum_comments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,topic_id BIGINT NOT NULL REFERENCES forum_topics(id) ON DELETE CASCADE,parent_comment_id BIGINT REFERENCES forum_comments(id) ON DELETE CASCADE,created_by BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'published' CHECK(status IN ('published','hidden','removed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_forum_comments_topic ON forum_comments(topic_id,created_at);
CREATE TABLE IF NOT EXISTS media_files(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,uploaded_by BIGINT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,storage_key TEXT NOT NULL UNIQUE,public_url TEXT NOT NULL,mime_type VARCHAR(100) NOT NULL,byte_size BIGINT NOT NULL CHECK(byte_size>0),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS forum_topic_media(topic_id BIGINT NOT NULL REFERENCES forum_topics(id) ON DELETE CASCADE,media_id BIGINT NOT NULL REFERENCES media_files(id) ON DELETE RESTRICT,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(topic_id,media_id));
CREATE TABLE IF NOT EXISTS forum_comment_media(comment_id BIGINT NOT NULL REFERENCES forum_comments(id) ON DELETE CASCADE,media_id BIGINT NOT NULL REFERENCES media_files(id) ON DELETE RESTRICT,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(comment_id,media_id));
CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,notification_type VARCHAR(50) NOT NULL DEFAULT 'general',title VARCHAR(180) NOT NULL,body TEXT NOT NULL,data JSONB NOT NULL DEFAULT '{}'::jsonb,read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_notifications_user_created ON notifications(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS app_settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value JSONB NOT NULL,description TEXT NOT NULL DEFAULT '',updated_by BIGINT REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS status_history(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,entity_type VARCHAR(60) NOT NULL,entity_id BIGINT NOT NULL,old_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,changed_by BIGINT REFERENCES users(id) ON DELETE SET NULL,note TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_status_history_entity ON status_history(entity_type,entity_id,created_at DESC);
CREATE TABLE IF NOT EXISTS admin_audit_log(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,admin_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(120) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT,details JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_admin_audit_created ON admin_audit_log(created_at DESC);

INSERT INTO roles(code,title) VALUES('user','کاربر'),('admin','مدیر') ON CONFLICT(code) DO NOTHING;
INSERT INTO permissions(code,description) VALUES
('admin.dashboard','دسترسی به داشبورد مدیریت'),('users.manage','مدیریت کاربران و نقش‌ها'),
('catalog.manage','مدیریت دسته‌بندی‌ها و محصولات'),('books.manage','مدیریت کتاب‌ها و درخواست‌های کتابخانه'),
('loans.manage','مدیریت امانت‌ها و تمدیدها'),('events.manage','مدیریت رویدادها و حضور و غیاب'),
('forum.topic.create','ایجاد موضوع در تالار'),('forum.moderate','مدیریت محتوای تالار'),
('media.manage','مدیریت فایل‌های رسانه‌ای'),('points.manage','مدیریت امتیازها'),('reports.view','مشاهده گزارش‌ها')
ON CONFLICT(code) DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code='admin' ON CONFLICT DO NOTHING;
COMMIT;
